WITH with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) AS prev_started_at FROM sessions), flagged AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged), latest_match AS (SELECT s.id, s.device, s.started_at, s.country, s.prev_started_at, s.new_group_flag, s.island_id, x.web_event_duration_sec, x.event_type FROM islands s LEFT JOIN LATERAL (SELECT c.duration_sec AS web_event_duration_sec, c.event_type FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) x ON TRUE), deduped AS (SELECT id, device, country, prev_started_at, island_id, web_event_duration_sec FROM latest_match QUALIFY ROW_NUMBER() OVER (PARTITION BY country, device ORDER BY web_event_duration_sec DESC NULLS LAST, id ASC) = 1), enriched AS (SELECT id, country, prev_started_at, web_event_duration_sec, NTILE(5) OVER (PARTITION BY country ORDER BY web_event_duration_sec ASC, id ASC) AS web_event_duration_sec_bucket, FIRST_VALUE(web_event_duration_sec, TRUE) OVER (ORDER BY web_event_duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_web_event_duration_sec FROM deduped), deduped_sessions AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY web_event_duration_sec ASC NULLS FIRST, id ASC) AS rn FROM enriched) ranked WHERE rn = 1), matched_keys AS (SELECT id, country FROM deduped_sessions INTERSECT SELECT id, country FROM sessions WHERE country IS NULL), verified AS (SELECT s.* FROM deduped_sessions s INNER JOIN matched_keys k ON s.id = k.id AND s.country = k.country), metrics AS (SELECT id, country, prev_started_at, web_event_duration_sec_bucket, first_known_web_event_duration_sec, RANK() OVER (ORDER BY web_event_duration_sec_bucket DESC) AS web_event_duration_sec_bucket_rank, COUNT(first_known_web_event_duration_sec) OVER (PARTITION BY country ORDER BY CAST(prev_started_at AS BIGINT) ASC RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS first_known_web_event_duration_sec_count_7d FROM verified) SELECT CASE WHEN web_event_duration_sec_bucket >= 7 THEN 'LARGE' ELSE 'SMALL' END AS web_event_duration_sec_bucket_tier, CASE WHEN first_known_web_event_duration_sec >= 411 THEN 'HIGH' ELSE 'LOW' END AS first_known_web_event_duration_sec_tier, CASE WHEN first_known_web_event_duration_sec_count_7d >= 18 THEN 'HIGH' ELSE 'LOW' END AS first_known_web_event_duration_sec_count_7d_tier, ROUND(SUM(web_event_duration_sec_bucket) / NULLIF(COUNT(CASE WHEN country = 'JP' THEN 1 END), 0), 2) AS web_event_duration_sec_bucket_per_jp, COUNT(*) AS event_count, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(*) FILTER (WHERE country = 'SG') AS sg_rows, SORT_ARRAY(COLLECT_SET(country)) AS country_list_2 FROM metrics GROUP BY web_event_duration_sec_bucket_tier, first_known_web_event_duration_sec_tier, first_known_web_event_duration_sec_count_7d_tier ORDER BY event_count ASC NULLS FIRST
